window.switchSpec = function(spec){
  var tabs = document.querySelectorAll('.vi-spec-tab');
  var panels = document.querySelectorAll('.vi-spec-panel');
  tabs.forEach(function(t){
    if(t.getAttribute('data-spec') === spec){
      t.classList.add('active');
      t.style.background = 'var(--rust)';
      t.style.color = 'white';
      t.style.borderColor = 'var(--rust)';
    } else {
      t.classList.remove('active');
      t.style.background = 'white';
      t.style.color = 'var(--ink-light)';
      t.style.borderColor = 'var(--border)';
    }
  });
  panels.forEach(function(p){
    if(p.getAttribute('data-spec') === spec){
      p.classList.add('active');
      p.style.display = '';
      // Re-apply grid for ortho (inline) or show inner grid for others
      if(spec === 'ortho'){
        p.style.display = 'grid';
      } else {
        p.style.display = 'block';
      }
    } else {
      p.classList.remove('active');
      p.style.display = 'none';
    }
  });
};
/* ──────────────────────────────────────────────────────────────────────
   QH Analytics Layer — dataLayer pushes for GA4 via GTM (GTM-535KTHSM).
   All events use snake_case names + event-scoped params:
     journey_stage, page_type, page_id, route
   No PII is ever pushed to dataLayer.
   ────────────────────────────────────────────────────────────────────── */
(function(){
  window.dataLayer = window.dataLayer || [];

  /* journey_stage by page id — used by every event fired on that page */
  var JOURNEY_STAGE = {
    home:'awareness', about:'awareness', blog:'awareness', glossary:'awareness',
    'blog-hospital-marketing':'awareness','blog-opd-footfall':'awareness',
    'blog-video-marketing':'awareness','blog-hospital-seo':'awareness',
    'blog-healthcare-agency':'awareness','blog-social-media-hospitals':'awareness',
    'blog-vs-generic-agencies':'awareness','blog-in-house-vs-agency':'awareness',
    'blog-hospital-video-production-india':'awareness','blog-hospital-content-marketing':'awareness',
    video:'consideration', seo:'consideration', paid:'consideration',
    social:'consideration', email:'consideration', opd:'consideration',
    contact:'intent',
    privacy:'utility', terms:'utility', '404':'utility'
  };
  var PAGE_TYPE = {
    home:'home', about:'about', blog:'blog_index', glossary:'glossary',
    contact:'contact', privacy:'legal', terms:'legal', '404':'error'
  };
  function pageType(id){
    if(PAGE_TYPE[id]) return PAGE_TYPE[id];
    if(id.indexOf('blog-')===0) return 'blog_post';
    return 'service';
  }

  /* qhTrack: single helper. All events go through here. */
  window.qhTrack = function(name, params){
    var ctx = window.qhPageContext || {};
    var payload = Object.assign({
      event: name,
      page_id: ctx.page_id || 'home',
      route: ctx.route || location.pathname,
      page_type: ctx.page_type || 'unknown',
      journey_stage: ctx.journey_stage || 'awareness'
    }, params || {});
    window.dataLayer.push(payload);
  };

  /* Wrap updateMeta so every page change refreshes context + fires page_view_qh */
  if(typeof updateMeta === 'function'){
    var _updateMeta = updateMeta;
    updateMeta = function(id){
      _updateMeta(id);
      var route = (typeof idToPath === 'function') ? '/'+idToPath(id) : location.pathname;
      window.qhPageContext = {
        page_id: id,
        route: route,
        page_type: pageType(id),
        journey_stage: JOURNEY_STAGE[id] || 'awareness'
      };
      qhTrack('page_view_qh', { page_title: document.title });
      __qhResetScrollDepth();
    };
    /* Fire once for the page that's already active at load time */
    setTimeout(function(){
      var active = document.querySelector('.page.active');
      if(active){
        var id = active.id.replace(/^page-/, '');
        var route = (typeof idToPath === 'function') ? '/'+idToPath(id) : location.pathname;
        window.qhPageContext = {
          page_id: id, route: route,
          page_type: pageType(id),
          journey_stage: JOURNEY_STAGE[id] || 'awareness'
        };
        qhTrack('page_view_qh', { page_title: document.title });
      }
    }, 0);
  }

  /* ── Delegated click handler: call / whatsapp / mailto / outbound / cta ── */
  document.addEventListener('click', function(e){
    var a = e.target.closest('a');
    if(a){
      var href = (a.getAttribute('href') || '').trim();
      var loc = a.getAttribute('data-cta-location') || locationOf(a);
      if(href.indexOf('tel:') === 0){
        qhTrack('call_click', { link_location: loc, phone_masked: maskPhone(href.slice(4)) });
        return;
      }
      if(/^https?:\/\/(wa\.me|api\.whatsapp\.com)/i.test(href) || /^whatsapp:/i.test(href)){
        qhTrack('whatsapp_click', { link_location: loc });
        return;
      }
      if(href.indexOf('mailto:') === 0){
        qhTrack('email_click', { link_location: loc });
        return;
      }
      if(/^https?:\/\//i.test(href) && href.indexOf(location.host) === -1){
        qhTrack('outbound_click', {
          link_location: loc,
          destination_domain: hostOf(href)
        });
        return;
      }
    }
    var cta = e.target.closest('[data-track]');
    if(cta){
      qhTrack(cta.getAttribute('data-track'), {
        cta_location: cta.getAttribute('data-cta-location') || locationOf(cta),
        cta_label: (cta.textContent || '').trim().slice(0, 80)
      });
    }
  }, true);

  function locationOf(el){
    var sec = el.closest('section,header,footer,[data-section]');
    if(sec){
      return sec.getAttribute('data-section')
        || sec.id
        || sec.tagName.toLowerCase();
    }
    return 'unknown';
  }
  function hostOf(url){ try { return new URL(url).hostname; } catch(_){ return ''; } }
  function maskPhone(p){ p = (p||'').replace(/[^\d+]/g,''); return p.length < 4 ? '***' : p.slice(0,3)+'***'+p.slice(-2); }

  /* ── Scroll depth: 25 / 50 / 75 / 90 per page activation ── */
  var __qhDepthFired = {};
  function __qhResetScrollDepth(){ __qhDepthFired = {}; }
  window.__qhResetScrollDepth = __qhResetScrollDepth;
  var thresholds = [25, 50, 75, 90];
  window.addEventListener('scroll', function(){
    var doc = document.documentElement;
    var scrolled = (window.scrollY + window.innerHeight);
    var height = doc.scrollHeight;
    if(height <= window.innerHeight) return;
    var pct = Math.round((scrolled / height) * 100);
    thresholds.forEach(function(t){
      if(pct >= t && !__qhDepthFired[t]){
        __qhDepthFired[t] = 1;
        qhTrack('scroll_depth', { depth_pct: t });
      }
    });
  }, { passive: true });

  /* ── Form attempt + form view (contact form #cf-form) ── */
  document.addEventListener('DOMContentLoaded', function(){
    var form = document.getElementById('cf-form');
    if(!form) return;
    var seen = false;
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(en){
        if(en.isIntersecting && !seen){
          seen = true;
          qhTrack('form_view', { form_id: 'cf-form', form_location: 'contact' });
          io.disconnect();
        }
      });
    }, { threshold: 0.4 });
    io.observe(form);
  });

  /* ── Capture GA4 client_id for CRM tie-back (C-08) ──────────────────────
     Strategy: try window.gtag('get') first (works when GA4 Config tag
     exposes it). If window.gtag is not defined (new Google Tag type in
     GTM routes internally without exposing window.gtag), fall back to
     reading the _ga cookie which GA4 always sets after the first hit.
     Cookie format: GA1.<version>.<random>.<timestamp> → cid = last two parts.
     Stored on window.qhClientId + injected as hidden #cf-form field so
     Web3Forms forwards the cid to the CRM. */
  function qhInjectCid(cid) {
    if (!cid) return;
    window.qhClientId = cid;
    var form = document.getElementById('cf-form');
    if (form && !form.querySelector('input[name="ga_client_id"]')) {
      var hi = document.createElement('input');
      hi.type = 'hidden';
      hi.name = 'ga_client_id';
      hi.value = cid;
      form.appendChild(hi);
    }
  }
  setTimeout(function(){
    /* Primary: gtag('get') — works when window.gtag is defined */
    if (typeof window.gtag === 'function') {
      try { window.gtag('get', 'G-PMSJHJ679P', 'client_id', qhInjectCid); } catch(_){}
      return;
    }
    /* Fallback: read _ga cookie — set by GA4 after first collect hit */
    var m = document.cookie.match(/_ga=GA\d+\.\d+\.(\d+\.\d+)/);
    if (m) { qhInjectCid(m[1]); return; }
    /* Last resort: retry once more after another 2s (cookie may not be set yet) */
    setTimeout(function(){
      var m2 = document.cookie.match(/_ga=GA\d+\.\d+\.(\d+\.\d+)/);
      if (m2) qhInjectCid(m2[1]);
    }, 2000);
  }, 1500);
})();

/* ── Per-page lead/audit form (.qh-lead-form) ───────────────────────────────
   One delegated handler powers the audit-form CTA on every service page.
   Submits to Web3Forms (same access key as the contact form). On success,
   the form-card swaps to a confirmation block. On failure, a WhatsApp
   fallback is offered so the lead never disappears. */
(function(){
  var WA_NUMBER = '918147410751';
  var W3F_KEY = '9d24ab4d-33de-4076-9f42-77aab943b9ab';

  function fields(form) {
    var out = {};
    Array.prototype.forEach.call(form.querySelectorAll('[data-field]'), function(el){
      var key = el.getAttribute('data-field');
      if (el.type === 'checkbox') out[key] = el.checked;
      else out[key] = (el.value || '').trim();
    });
    return out;
  }
  function validate(form) {
    var ok = true;
    Array.prototype.forEach.call(form.querySelectorAll('[data-required]'), function(el){
      var group = el.closest('.form-group');
      var val = (el.type === 'checkbox') ? el.checked : (el.value || '').trim();
      var valid = !!val;
      if (el.type === 'email') valid = valid && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val);
      if (group) {
        group.classList.remove('has-error','is-valid');
        group.classList.add(valid ? 'is-valid' : 'has-error');
      }
      if (!valid) ok = false;
    });
    return ok;
  }
  function buildWaUrl(data) {
    var msg = "Hi, I'd like a free YouTube audit"
      + (data.hospital ? ' for ' + data.hospital : '')
      + '. ' + (data.name ? 'My name is ' + data.name + '. ' : '')
      + (data.phone ? 'Best number: ' + data.phone + '. ' : '')
      + 'Looking forward to hearing from you!';
    return 'https://wa.me/' + WA_NUMBER + '?text=' + encodeURIComponent(msg);
  }
  function showSuccess(form, data) {
    // Fire Google Ads conversion event
    if (typeof gtag === 'function') {
      gtag('event', 'conversion', {
        'send_to': 'AW-18175807482/iCh7CKmol7AcEPqf89pD',
        'value': 1.0,
        'currency': 'INR'
      });
    }
    var card = form.closest('.form-card');
    if (!card) return;
    var name = (data.name || '').split(' ')[0];
    var greeting = name ? 'Thanks, ' + name + '.' : 'You\'re in.';
    var hospitalLine = data.hospital ? ' for <strong>' + data.hospital + '</strong>' : '';
    card.innerHTML =
      '<div style="text-align:center;padding:8px 0;">'
      + '<div style="width:56px;height:56px;border-radius:50%;background:var(--rust-pale);color:var(--rust);display:flex;align-items:center;justify-content:center;font-size:28px;margin:0 auto 16px;">✓</div>'
      + '<div style="font-family:\'Source Serif 4\',serif;font-size:26px;font-weight:700;line-height:1.15;color:var(--ink);margin-bottom:10px;">' + greeting + '</div>'
      + '<p style="font-size:15px;color:var(--ink-light);line-height:1.65;max-width:340px;margin:0 auto 8px;">Your audit request' + hospitalLine + ' is confirmed.</p>'
      + '<p style="font-size:13px;color:var(--ink-light);line-height:1.6;max-width:320px;margin:0 auto 22px;">We\'ll review your digital presence and send a written report — specific to your specialty mix, city, and competitors — to <strong>' + (data.email || 'your inbox') + '</strong> within 48 hours.</p>'
      + '<a href="' + buildWaUrl(data) + '" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:8px;padding:13px 24px;border-radius:100px;background:var(--ink);color:#fff;text-decoration:none;font-size:13px;font-weight:600;margin-bottom:14px;">Message us on WhatsApp →</a>'
      + '<p style="font-family:\'JetBrains Mono\',monospace;font-size:10px;color:var(--ink-light);text-transform:uppercase;letter-spacing:.1em;margin:0;">Report in 48 hrs · No commitment</p>'
      + '</div>';
  }
  function showFallback(form, data, status) {
    var st = form.querySelector('.qh-lead-status');
    if (!st) return;
    st.innerHTML =
      '<div style="color:#b32424;margin-bottom:8px;">'
      + (status || 'Couldn\'t send right now.')
      + '</div>'
      + '<a href="' + buildWaUrl(data) + '" target="_blank" rel="noopener" style="color:var(--rust);font-weight:600;text-decoration:underline;text-underline-offset:3px;">Send via WhatsApp instead →</a>';
  }
  function submit(form) {
    var btn = form.querySelector('.qh-lead-submit');
    if (!btn || btn.disabled) return;
    if (!validate(form)) {
      var first = form.querySelector('.has-error');
      if (first) {
        var inp = first.querySelector('input,select,textarea');
        if (inp) inp.focus();
      }
      return;
    }
    var data = fields(form);
    var location = form.getAttribute('data-form-location') || 'unknown';

    btn.disabled = true;
    var origLabel = btn.innerHTML;
    btn.innerHTML = 'Sending…';

    window.qhTrack && qhTrack('form_attempt', {
      form_id: 'qh-lead-form', form_location: location, valid: true
    });

    var fd = new FormData();
    fd.append('access_key', W3F_KEY);
    fd.append('subject', 'New audit request from /' + location);
    fd.append('from_name', 'Qlarify Health Website');
    fd.append('Hospital', data.hospital || '');
    fd.append('Name', data.name || '');
    fd.append('Email', data.email || '');
    fd.append('Phone', data.phone || '');
    fd.append('Website', data.website || '');
    fd.append('Page', location);
    if (window.qhClientId) fd.append('ga_client_id', window.qhClientId);

    fetch('https://api.web3forms.com/submit', { method: 'POST', body: fd })
      .then(function(r){ return r.json(); })
      .then(function(j){
        if (j && j.success) {
          window.qhTrack && qhTrack('lead_form_submit', {
            form_id: 'qh-lead-form', form_location: location, lead_type: 'audit_form'
          });
          showSuccess(form, data);
        } else {
          btn.disabled = false; btn.innerHTML = origLabel;
          showFallback(form, data, 'Something went wrong.');
          window.qhTrack && qhTrack('form_error', { form_id: 'qh-lead-form', error_type: 'api_failure' });
        }
      })
      .catch(function(){
        btn.disabled = false; btn.innerHTML = origLabel;
        showFallback(form, data, 'Network error.');
        window.qhTrack && qhTrack('form_error', { form_id: 'qh-lead-form', error_type: 'network_error' });
      });
  }

  /* Delegated click + blur listeners — work for forms injected dynamically too. */
  document.addEventListener('click', function(e){
    var btn = e.target.closest && e.target.closest('.qh-lead-submit');
    if (!btn) return;
    var form = btn.closest('.qh-lead-form');
    if (!form) return;
    e.preventDefault();
    submit(form);
  });
  document.addEventListener('blur', function(e){
    var el = e.target;
    if (!el || !el.matches || !el.matches('.qh-lead-form [data-required]')) return;
    var group = el.closest('.form-group');
    if (!group) return;
    var val = (el.type === 'checkbox') ? el.checked : (el.value || '').trim();
    var valid = !!val;
    if (el.type === 'email') valid = valid && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val);
    group.classList.remove('has-error','is-valid');
    group.classList.add(valid ? 'is-valid' : 'has-error');
  }, true);
})();

/* ── Audit form (#audit-form) ──────────────────────────────────────────────── */
(function(){
  var form = document.getElementById('audit-form');
  if (!form) return;

  document.getElementById('af-submit').addEventListener('click', function(e){
    e.preventDefault();
    var hospital = (document.getElementById('af-hospital').value||'').trim();
    var name     = (document.getElementById('af-name').value||'').trim();
    var city     = (document.getElementById('af-city').value||'').trim();
    var email    = (document.getElementById('af-email').value||'').trim();
    var consent  = document.getElementById('af-consent').checked;
    var challenge= (document.getElementById('af-challenge').value||'').trim();
    var ok = true;

    ['af-hospital','af-name','af-city','af-email'].forEach(function(id){
      var el = document.getElementById(id);
      var g  = el.closest('.form-group');
      var v  = (el.tagName==='SELECT'?el.value:el.value||'').trim();
      var valid = !!v;
      if(id==='af-email') valid = valid && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
      g.classList.toggle('has-error', !valid);
      if(!valid) ok = false;
    });
    var ce = document.getElementById('af-consent-error');
    ce.style.display = consent ? 'none' : 'block';
    if(!consent) ok = false;
    if(!ok) return;

    var btn = document.getElementById('af-submit');
    btn.disabled = true;
    btn.textContent = 'Sending…';

    var fd = new FormData();
    fd.append('access_key', '9d24ab4d-33de-4076-9f42-77aab943b9ab');
    fd.append('subject', 'New Video ROI Audit request — ' + hospital);
    fd.append('from_name', 'Qlarify Health Website');
    fd.append('Hospital', hospital);
    fd.append('Name', name);
    fd.append('City', city);
    fd.append('Email', email);
    if (challenge) fd.append('Challenge', challenge);

    fetch('https://api.web3forms.com/submit', { method: 'POST', body: fd })
    .then(function(r){ return r.json(); })
    .then(function(data){
      if (data && data.success) {
        form.style.display = 'none';
        document.getElementById('af-success').style.display = 'block';
        window.qhTrack && qhTrack('lead_form_submit',{ form_id:'audit-form', form_location:'audit', lead_type:'audit' });
      } else {
        btn.disabled = false;
        btn.textContent = 'Book your free Video ROI Audit →';
        document.getElementById('af-fallback').style.display = 'block';
      }
    })
    .catch(function(){
      btn.disabled = false;
      btn.textContent = 'Book your free Video ROI Audit →';
      document.getElementById('af-fallback').style.display = 'block';
    });
  });
})();

document.addEventListener('DOMContentLoaded', function(){
  var pg = document.querySelector('.page.active');
  if (pg) { placeTopLeadForm(pg); placeArticleCta(pg); }
});
